const KEY='astralis:hsr:workspace:v1';
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return {}}};
const write=value=>localStorage.setItem(KEY,JSON.stringify(value));
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const id=()=>globalThis.crypto?.randomUUID?.()||`hsr-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const routes={
 'hsr-dashboard':['Pont de commandement','L’Astral Express · tableau Star Rail'],
 'hsr-builds':['Atelier de builds','Builds Star Rail'],
 'hsr-lab':['Laboratoire HSR','Calcul de dégâts'],
 'hsr-calc':['Calc Sheets HSR','Comparateur d’escouades'],
 'hsr-farm':['Plan de farm HSR','Progression des personnages'],
 'hsr-endgame':['Endgame HSR','Mémoire du Chaos · Fiction pure · Ombre apocalyptique'],
 'hsr-currency-wars':['Currency Wars','Suivi de saison · Bonds · équipe de dix'],
 'hsr-wishes':['Warp & objectifs','Pity, passes et objectifs'],
 'hsr-events':['Agenda Star Rail','Événements et cycles'],
 'hsr-lore':['Archives Star Rail','Personnages, factions et récits']
};
const slots=[['head','Tête','PV fixe'],['hands','Mains','ATQ fixe'],['body','Corps','ATQ %'],['feet','Pieds','VIT'],['sphere','Planar','Bonus de DGT'],['rope','Corde','Recharge d’énergie']];
const mainStats=['PV fixe','ATQ fixe','PV %','ATQ %','DÉF %','VIT','Taux CRIT','DGT CRIT','Toucher des effets','RÉS aux effets','Bonus de DGT physique','Bonus de DGT feu','Bonus de DGT glace','Bonus de DGT foudre','Bonus de DGT vent','Bonus de DGT quantique','Bonus de DGT imaginaire','Recharge d’énergie','Effet de rupture'];
const slotMainStats={head:['PV fixe'],hands:['ATQ fixe'],body:['PV %','ATQ %','DÉF %','Taux CRIT','DGT CRIT','Toucher des effets','Bonus de soins'],feet:['PV %','ATQ %','DÉF %','VIT'],sphere:['PV %','ATQ %','DÉF %','Bonus de DGT physique','Bonus de DGT feu','Bonus de DGT glace','Bonus de DGT foudre','Bonus de DGT vent','Bonus de DGT quantique','Bonus de DGT imaginaire'],rope:['PV %','ATQ %','DÉF %','Recharge d’énergie','Effet de rupture']};
const statFields=[['hp','PV'],['atk','ATQ'],['def','DÉF'],['spd','VIT'],['critRate','Taux CRIT %'],['critDmg','DGT CRIT %'],['breakEffect','Effet de rupture %'],['effectHit','Toucher des effets %'],['effectRes','RÉS aux effets %'],['energy','Recharge %']];
function defaults(){return {builds:[],calc:[],farm:{},endgame:[],warp:{jade:0,passes:0,special:0,charPity:0,charGuarantee:false,lightPity:0,lightGuarantee:false},agenda:[],dashboardDaily:{date:'',done:[]},dashboardWeekly:{week:'',done:[],tasks:[{id:'weekly-boss',label:'Défis hebdomadaires',hint:'Progression du boss hebdomadaire'},{id:'weekly-endgame',label:'Modes d’endgame',hint:'Mémoire du Chaos, Fiction pure ou Ombre'},{id:'weekly-currency',label:'Currency Wars',hint:'Points et récompenses de la semaine'}]},currencyWar:{season:'Voyage Into the Canvas',weekKey:'',weeklyPoints:0,ascensionPoints:0,rank:'',employees:[],bonds:[],runs:[],firstStandard:false,firstOverclock:false,reminder:true,serverReset:'04:00'}}}
function image(row){return row?.icon||row?.portrait||row?.images?.icon||row?.images?.filename_icon||''}
function icon(row){const src=image(row);return src?`<img src="${esc(src)}" alt="" loading="lazy" decoding="async" width="48" height="48" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="hsr-avatar-fallback" hidden>✦</span>`:'<span class="hsr-avatar-fallback">✦</span>'}
function options(rows,selected,placeholder='Choisir…'){return `<option value="">${placeholder}</option>${rows.map(row=>`<option value="${esc(row._id)}" ${String(selected||'')===String(row._id)?'selected':''}>${esc(row._name)}</option>`).join('')}`}
function card(title,eyebrow,body,iconText='✦'){return `<section class="hsr-panel"><header><span class="hsr-panel-mark">${iconText}</span><div><small>${esc(eyebrow)}</small><h3>${esc(title)}</h3></div></header>${body}</section>`}
let fieldMode='field';
function field(label,name,value='',type='text',attrs=''){const attribute=fieldMode==='lab'?'data-hsr-lab':fieldMode==='warp'?'data-hsr-warp':fieldMode==='war'?'data-hsr-war':'data-hsr-field';return `<label class="hsr-field">${esc(label)}<input type="${type}" ${attribute}="${name}" value="${esc(value)}" ${attrs}></label>`}
function labField(...args){const before=fieldMode;fieldMode='lab';const html=field(...args);fieldMode=before;return html}
function warpField(...args){const before=fieldMode;fieldMode='warp';const html=field(...args);fieldMode=before;return html}
function characterOptions(chars,selected){return options(chars,selected,'Personnage')}
function renderBuilds(data,chars,cones,relics){
 const chosen=data.buildDraft||{};const chosenChar=chars.find(x=>String(x._id)===String(chosen.character));
 const active=data.builds.find(x=>x.id===data.activeBuild);
 const draft=active||chosen;
 const gear=Array.isArray(draft.relics)?draft.relics:slots.map(()=>({set:'',main:'',level:15,subs:''}));
 const stats=Object.fromEntries(statFields.map(([k])=>[k,draft.stats?.[k]??'']));
 return `<section class="hsr-workspace-hero"><div><span>HONKAI: STAR RAIL · ÉQUIPEMENT</span><h2>Un atelier pensé pour six reliques</h2><p>Enregistre tes cônes, reliques, niveaux et statistiques. Les valeurs restent distinctes des builds Genshin et ne sont jamais déduites avec de mauvaises formules.</p></div><div class="hsr-hero-orbit">✦</div></section>
 <div class="hsr-workspace-grid">${card('Configuration du build','PERSONNAGE & CÔNE',`<div class="hsr-form-grid"><label class="hsr-field">Personnage<select data-hsr-field="character">${characterOptions(chars,draft.character)}</select></label><label class="hsr-field">Cône de lumière<select data-hsr-field="lightCone">${options(cones,draft.lightCone,'Sans cône')}</select></label>${field('Nom du build','buildName',draft.name||'Build 1')}${field('Niveau personnage','level',draft.level??80,'number','min="1" max="80"')}${field('Eidolon','eidolon',draft.eidolon??0,'number','min="0" max="6"')}${field('Niveau du cône','coneLevel',draft.coneLevel??80,'number','min="1" max="80"')}</div><div class="hsr-save-row"><button class="button-primary" data-hsr-action="save-build">Enregistrer le build</button><button class="quiet-btn" data-hsr-action="new-build">Nouveau</button>${draft.id?`<button class="quiet-btn danger" data-hsr-action="delete-build">Supprimer</button>`:''}</div>`,'✧')}
 ${card('Reliques équipées','SIX EMPLACEMENTS · STATS PRINCIPALES & SOUS-STATS',`<div class="hsr-relic-grid">${slots.map(([key,label,base],index)=>{const r=gear[index]||{},valid=slotMainStats[key]||mainStats;return `<article class="hsr-relic-card"><div class="hsr-relic-heading"><b>${label}</b><small>${base}</small></div><label class="hsr-field">Set<select data-hsr-relic="${index}" data-relic-field="set">${options(relics,r.set,'Choisir un set')}</select></label><div class="hsr-form-grid compact"><label class="hsr-field">Stat principale<select data-hsr-relic="${index}" data-relic-field="main">${options(valid.map((name,i)=>({_id:name,_name:name})),r.main||base,'Choisir')}</select></label>${field('Niveau','level',r.level??15,'number',`min="0" max="15" data-hsr-relic="${index}" data-relic-field="level"`)}</div><label class="hsr-field">Sous-stats <textarea data-hsr-relic="${index}" data-relic-field="subs" placeholder="ATQ % · 8,1 | Taux CRIT · 3,2 | VIT · 5">${esc(r.subs||'')}</textarea></label></article>`}).join('')}</div><p class="hsr-note">Les stats principales sont filtrées selon l’emplacement HSR; les sous-stats restent éditables. Les statistiques affichées plus haut sont celles que tu observes en jeu, pas une estimation automatique du build.</p>`,'◈')}
 ${card('Statistiques observées','VALEURS DU PERSONNAGE ÉQUIPÉ',`<div class="hsr-stat-grid">${statFields.map(([key,label])=>field(label,key,stats[key],'number','step="any" min="0"')).join('')}</div><p class="hsr-note">Saisis les stats du personnage telles qu’elles apparaissent en jeu ou importe ton profil HoYoLAB. Astralis n’invente pas les bonus de set tant qu’ils ne sont pas activés dans le labo.</p>`,'⌁')}</div>
 <section class="hsr-saved-builds"><header><div><small>SAUVEGARDES LOCALES</small><h3>Mes builds Star Rail <b>${data.builds.length}</b></h3></div></header><div class="hsr-build-list">${data.builds.map(build=>{const char=chars.find(x=>String(x._id)===String(build.character));return `<button class="hsr-build-row ${build.id===data.activeBuild?'active':''}" data-hsr-load-build="${esc(build.id)}">${icon(char)}<span><b>${esc(build.name||'Build sans nom')}</b><small>${esc(char?._name||'Personnage')} · ${build.relics?.filter(x=>x.set).length||0}/6 reliques · E${Number(build.eidolon)||0}</small></span><i>›</i></button>`}).join('')||'<p class="hsr-note">Aucun build enregistré pour le moment.</p>'}</div></section>`;
}
function renderLab(data,chars){
 const l=data.lab||{};const mult=(Number(l.multiplier)||0)/100,atk=Number(l.atk)||0,extra=Number(l.extraDamage)||0,base=atk*mult+extra,bonus=(Number(l.damageBonus)||0)/100,cr=Math.min(100,Math.max(0,Number(l.critRate)||0))/100,cd=(Number(l.critDmg)||0)/100,enemy=Number(l.enemyLevel)||95,charLevel=Number(l.charLevel)||80,defShred=Math.min(1,Math.max(-1,Number(l.defShred)||0)/100),enemyDef=(Number(l.enemyDefense)||200+10*enemy)*(1-defShred),defMult=(200+10*charLevel)/(200+10*charLevel+enemyDef),res=Math.max(-1,Math.min(.9,(Number(l.enemyRes??20))/100-(Number(l.resPen)||0)/100)),resMult=1-res,vuln=1+(Number(l.vulnerability)||0)/100,reduction=l.broken?1:1-(Number(l.universalReduction??10)||0)/100,expected=base*(1+bonus)*(1+cr*cd)*defMult*resMult*vuln*reduction,crit=base*(1+bonus)*(1+cd)*defMult*resMult*vuln*reduction,noncrit=base*(1+bonus)*defMult*resMult*vuln*reduction;
 return `<section class="hsr-workspace-hero combat"><div><span>COMBAT LAB · HONKAI: STAR RAIL</span><h2>Mesure une action, puis une rotation</h2><p>Le calcul expose chaque facteur (bonus, CRIT, défense, résistance et vulnérabilité). Les multiplicateurs de kit restent éditables pour éviter les valeurs inventées.</p></div><div class="hsr-damage-orb">${Math.round(expected).toLocaleString('fr-FR')}<small>DGT moyens</small></div></section>
 <div class="hsr-lab-layout">${card('Action testée','KIT HSR',`<div class="hsr-form-grid"><label class="hsr-field">Personnage<select data-hsr-lab="character">${characterOptions(chars,l.character)}</select></label><label class="hsr-field">Action<select data-hsr-lab="action">${options(['Attaque de base','Compétence','Ultime','Talent','Technique','Attaque de suivi','Dégâts de rupture','Autre'].map(x=>({_id:x,_name:x})),l.action||'Compétence')}</select></label>${field('Multiplicateur (%)','multiplier',l.multiplier||'','number','step="any" min="0" placeholder="ex. 240"')}<label class="hsr-field">Stat de référence<select data-hsr-lab="scaleStat">${options(['ATQ','PV','DÉF'].map(x=>({_id:x,_name:x})),l.scaleStat||'ATQ')}</select></label>${field('Valeur de la stat','atk',l.atk||'','number','step="any" min="0"')}${field('DGT fixes ajoutés','extraDamage',l.extraDamage||0,'number','step="any" min="0"')}${field('Bonus de dégâts (%)','damageBonus',l.damageBonus||0,'number','step="any"')}${field('Taux CRIT (%)','critRate',l.critRate||0,'number','step="any" min="0" max="100"')}${field('DGT CRIT (%)','critDmg',l.critDmg||50,'number','step="any" min="0"')}${field('Niveau personnage','charLevel',l.charLevel||80,'number','min="1" max="80"')}${field('Niveau ennemi','enemyLevel',l.enemyLevel||95,'number','min="1" max="100"')}${field('DEF ennemie personnalisée','enemyDefense',l.enemyDefense||'','number','min="0" placeholder="Vide = estimation par niveau"')}${field('RÉS ennemie (%)','enemyRes',l.enemyRes??20,'number','step="any"')}${field('Pénétration de RÉS (%)','resPen',l.resPen||0,'number','step="any"')}${field('Réduction DÉF (%)','defShred',l.defShred||0,'number','step="any"')}${field('Vulnérabilité reçue (%)','vulnerability',l.vulnerability||0,'number','step="any"')}${field('Réduction universelle (%)','universalReduction',l.universalReduction??10,'number','step="any"')}<label class="hsr-check"><input type="checkbox" data-hsr-lab="broken" ${l.broken?'checked':''}> Ennemi en état de rupture</label></div><p class="hsr-note">Les kits HSR peuvent évoluer avec les niveaux et les Eidolons : saisis le multiplicateur exact du coup visé. Pour une attaque multi-coups, ajoute chaque coup à la rotation avec son propre multiplicateur ou utilise le nombre de coups dans la séquence.</p>`,'⚔')}
 <aside class="hsr-result-card"><small>RÉSULTAT DE L’ACTION</small><strong>${Math.round(expected).toLocaleString('fr-FR')}</strong><span>Dégâts moyens attendus</span><div class="hsr-result-breakdown"><p><b>${Math.round(noncrit).toLocaleString('fr-FR')}</b><small>Sans CRIT</small></p><p><b>${Math.round(crit).toLocaleString('fr-FR')}</b><small>CRIT</small></p><p><b>×${defMult.toFixed(3)}</b><small>Défense</small></p><p><b>×${resMult.toFixed(3)}</b><small>Résistance</small></p></div><details><summary>Formule et hypothèses</summary><p>(Stat de référence × multiplicateur + dégâts fixes) × bonus de dégâts × CRIT × défense × résistance × vulnérabilité × réduction universelle. La DEF ennemie est estimée depuis son niveau (200 + 10 × niveau) sauf si tu saisis une valeur; la réduction de DEF s’applique ensuite. La pén. de RÉS, vulnérabilité et réduction sont des champs séparés. La rupture supprime ici la réduction universelle configurée; dégâts de rupture spécialisés et bonus de kit doivent être ajoutés séparément. Modèle de défense/résistance aligné sur la <a href="https://www.prydwen.gg/star-rail/guides/damage-formula" target="_blank" rel="noopener noreferrer">référence HSR</a>.</p></details></aside></div>
 ${card('Séquence de combat','ROTATION PERSONNELLE',`<p>Ajoute tes actions dans l’ordre et saisis leurs dégâts observés ou calculés. La somme et le DPS de rotation sont mis à jour sans assimiler les attaques multi-coups à un seul coup.</p><div class="hsr-sequence-add">${field('Nom de l’action','sequenceName','','text','placeholder="Ultime · 3 coups"')}${field('Dégâts par coup','sequenceDamage','','number','min="0" step="any"')}${field('Nombre de coups','sequenceHits',1,'number','min="1" max="30"')}<button data-hsr-action="add-hit">Ajouter</button></div><div class="hsr-sequence-list">${(l.sequence||[]).map((row,i)=>`<article><b>${esc(row.name)}</b><span>${Number(row.hits)||1} × ${Number(row.damage||0).toLocaleString('fr-FR')} = <strong>${((Number(row.hits)||1)*(Number(row.damage)||0)).toLocaleString('fr-FR')}</strong></span><button data-hsr-remove-hit="${i}" aria-label="Retirer">×</button></article>`).join('')||'<p class="hsr-note">Aucune action ajoutée à la rotation.</p>'}</div>${field('Durée de la rotation (secondes)','rotationDuration',l.rotationDuration||20,'number','min="1" step="any"')}<div class="hsr-sequence-total"><span>Dégâts saisis</span><b>${(l.sequence||[]).reduce((sum,row)=>sum+(Number(row.hits)||1)*(Number(row.damage)||0),0).toLocaleString('fr-FR')}</b><span>DPS de rotation</span><b>${Math.round((l.sequence||[]).reduce((sum,row)=>sum+(Number(row.hits)||1)*(Number(row.damage)||0),0)/(Number(l.rotationDuration)||20)).toLocaleString('fr-FR')}</b></div>`,'↗')}`;
}
function renderCalc(data,teams){const rows=[...teams.map(team=>({id:`team:${team.id}`,name:team.name,rotation:team.rotationNotes||team.rotation?.map(a=>a.character).join(' → ')||'',dpr:team.dpr||'',dps:team.dps||'',cycle:team.time||''})),...data.calc];return `<section class="hsr-workspace-hero"><div><span>CALC SHEETS · HSR</span><h2>Compare tes escouades et tes cycles</h2><p>Les équipes existantes sont importées comme point de départ. Complète les résultats par cycle ou par rotation selon le mode de jeu.</p></div></section>${card('Nouvelle comparaison','DPR · DPS · CYCLES',`<button class="button-primary" data-hsr-action="new-calc">＋ Ajouter une escouade</button><div class="hsr-calc-table"><table><thead><tr><th>Équipe / configuration</th><th>Dégâts par cycle</th><th>DPS moyen</th><th>Cycles / temps</th><th>Rotation</th><th></th></tr></thead><tbody>${rows.map((row,i)=>`<tr>${row.id.startsWith('team:')?`<td><b>${esc(row.name)}</b><small>Équipe Star Rail</small></td>`:`<td><input data-hsr-calc="${i-teams.length}" data-calc-field="name" value="${esc(row.name)}" placeholder="Nom de l’escouade"></td>`}<td>${row.id.startsWith('team:')?esc(row.dpr||'—'):`<input data-hsr-calc="${i-teams.length}" data-calc-field="dpr" value="${esc(row.dpr)}" type="number" min="0">`}</td><td>${row.id.startsWith('team:')?esc(row.dps||'—'):`<input data-hsr-calc="${i-teams.length}" data-calc-field="dps" value="${esc(row.dps)}" type="number" min="0">`}</td><td>${row.id.startsWith('team:')?esc(row.cycle||'—'):`<input data-hsr-calc="${i-teams.length}" data-calc-field="cycle" value="${esc(row.cycle)}" placeholder="Cycle / s">`}</td><td>${row.id.startsWith('team:')?esc(row.rotation||'À compléter'):`<input data-hsr-calc="${i-teams.length}" data-calc-field="rotation" value="${esc(row.rotation)}" placeholder="Rotation">`}</td><td>${row.id.startsWith('team:')?'':'<button data-hsr-delete-calc="'+(i-teams.length)+'">×</button>'}</td></tr>`).join('')||'<tr><td colspan="6">Crée une comparaison ou enregistre d’abord une équipe.</td></tr>'}</tbody></table></div>`,'◫')}`}
function renderFarm(data,chars,materials){const goals=data.farm||{},rows=Object.entries(goals);return `<section class="hsr-workspace-hero"><div><span>PROGRESSION · STAR RAIL</span><h2>Plan de farm sans règles empruntées à Teyvat</h2><p>Répertorie les objectifs par personnage, traces, ascension, crédits, boss hebdomadaire et reliques. Les coûts se règlent selon ton niveau et tes priorités.</p></div></section>${card('Ajouter un objectif','PERSONNAGE · RESSOURCE',`<div class="hsr-form-grid"><label class="hsr-field">Personnage<select data-hsr-farm="character">${characterOptions(chars,'')}</select></label><label class="hsr-field">Matériau<select data-hsr-farm="material">${options(materials,'','Ressource / matériau')}</select></label>${field('Quantité nécessaire','needed','','number','min="0"')}${field('Quantité possédée','owned',0,'number','min="0"')}<label class="hsr-field">Catégorie<select data-hsr-farm="kind">${options(['Ascension','Traces','Boss hebdomadaire','Crédits','EXP','Reliques','Autre'].map(x=>({_id:x,_name:x})),'Traces')}</select></label><button class="button-primary" data-hsr-action="add-farm">Ajouter au plan</button></div><div class="hsr-farm-list">${rows.map(([key,row])=>`<article>${icon(chars.find(x=>String(x._id)===String(row.character)))}<span><b>${esc(row.characterName)} · ${esc(row.materialName)}</b><small>${esc(row.kind)} · ${Math.max(0,Number(row.needed)-Number(row.owned))} restant(s)</small></span><progress max="${Math.max(1,Number(row.needed))}" value="${Math.min(Number(row.needed),Number(row.owned))}"></progress><button data-hsr-delete-farm="${esc(key)}">×</button></article>`).join('')||'<p class="hsr-note">Aucun objectif de farm ajouté.</p>'}</div>`,'⌂')}${card('Bibliothèque de ressources','CATALOGUE HSR',`<p>${materials.length} matériaux disponibles dans la base locale. Associe-les à un personnage pour créer des objectifs de farm ciblés.</p><div class="hsr-material-chips">${materials.slice(0,18).map(row=>`<span>${icon(row)}${esc(row._name)}</span>`).join('')}</div>`,'◌')}`}
function renderEndgame(data,teams){const modes=['Mémoire du Chaos','Fiction pure','Ombre apocalyptique','Univers simulé','Univers différencié'];return `<section class="hsr-workspace-hero"><div><span>ENDGAME · HONKAI: STAR RAIL</span><h2>Prépare les deux côtés, garde tes résultats</h2><p>Suivi local des cycles et performances. Les rotations et scores ne sont pas supposés être des données officielles en direct.</p></div></section>${card('Nouvelle session','CYCLE & ESCouADES',`<div class="hsr-form-grid">${field('Nom du cycle / défi','endgameName','','text','placeholder="Mémoire du Chaos · cycle 1"')}<label class="hsr-field">Mode<select data-hsr-endgame="mode">${options(modes.map(x=>({_id:x,_name:x})),modes[0])}</select></label>${field('Côté 1 · cycles / score','side1','','text')}${field('Côté 2 · cycles / score','side2','','text')}${field('Date','date',new Date().toISOString().slice(0,10),'date')}<label class="hsr-field">Équipe enregistrée<select data-hsr-endgame="team">${options(teams.map(x=>({_id:x.id,_name:x.name})),'','Optionnel')}</select></label><label class="hsr-field full">Notes / rotation<textarea data-hsr-endgame="notes" placeholder="Ordre des actions, faiblesses, vitesse, échecs…"></textarea></label><button class="button-primary" data-hsr-action="save-endgame">Enregistrer la session</button></div><div class="hsr-endgame-list">${data.endgame.map((row,i)=>`<article><div><small>${esc(row.mode)} · ${esc(row.date)}</small><h4>${esc(row.name)}</h4><p>${esc(row.teamName||'Équipe non liée')} · Côté 1 ${esc(row.side1||'—')} · Côté 2 ${esc(row.side2||'—')}</p><details><summary>Rotation & notes</summary><p>${esc(row.notes||'Pas de notes')}</p></details></div><button data-hsr-delete-endgame="${i}">×</button></article>`).join('')||'<p class="hsr-note">Tes sessions apparaîtront ici.</p>'}</div>`,'⚑')}`}
function renderWarp(data){const w=data.warp;const charWorst=Math.max(0,90-Number(w.charPity))*(w.charGuarantee?1:2),lcWorst=Math.max(0,80-Number(w.lightPity))*(w.lightGuarantee?1:2),pulls=Number(w.passes)+Number(w.special)+Math.floor(Number(w.jade)/160);return `<section class="hsr-workspace-hero warp"><div><span>WARP TRACKER · HONKAI: STAR RAIL</span><h2>Ton prochain 5★, ton budget, tes objectifs</h2><p>Suivi distinct pour les bannières de personnage et de cône. Les estimations de pire cas appliquent les plafonds de 90 et 80 sauts, sans transposer la Capture de radiance de Genshin.</p></div><div class="hsr-hero-number">${pulls}<small>sauts disponibles</small></div></section><div class="hsr-warp-grid">${card('Personnage événement','PITY MAX. 90',`${field('Pity actuelle','charPity',w.charPity,'number','min="0" max="89"')}<label class="hsr-check"><input type="checkbox" data-hsr-warp="charGuarantee" ${w.charGuarantee?'checked':''}> Vedette garantie au prochain 5★</label><div class="hsr-warp-total"><small>Pire cas jusqu’à la vedette</small><b>${charWorst} sauts · ${Math.max(0,charWorst-pulls)} encore à économiser</b></div>`,'✦')}${card('Cône de lumière événement','PITY MAX. 80',`${field('Pity actuelle','lightPity',w.lightPity,'number','min="0" max="79"')}<label class="hsr-check"><input type="checkbox" data-hsr-warp="lightGuarantee" ${w.lightGuarantee?'checked':''}> Cône vedette garanti au prochain 5★</label><div class="hsr-warp-total"><small>Pire cas jusqu’au cône vedette</small><b>${lcWorst} sauts · ${Math.max(0,lcWorst-pulls)} encore à économiser</b></div>`,'◈')}</div>${card('Portefeuille Star Rail','RESSOURCES DU COMPTE',`<div class="hsr-form-grid">${field('Jades stellaires','jade',w.jade,'number','min="0"')}${field('Passes spéciales','special',w.special,'number','min="0"')}${field('Passes Star Rail','passes',w.passes,'number','min="0"')}</div><button class="button-primary" data-hsr-action="save-warp">Enregistrer les ressources</button><p class="hsr-note">La garantie et la pity sont modifiables ci-dessus. L’estimation est un plafond de sécurité, pas une prédiction de la pity douce.</p>`,'✧')}`}
function renderAgenda(data){return `<section class="hsr-workspace-hero"><div><span>AGENDA STAR RAIL</span><h2>Cycles, sorties et événements à suivre</h2><p>Ajoute tes dates locales. Les périodes officielles sont affichées quand tu les as renseignées; rien n’est fabriqué en cas d’absence de flux vérifié.</p></div></section>${card('Ajouter un repère','AGENDA PERSONNEL',`<div class="hsr-form-grid">${field('Titre','agendaTitle','','text','placeholder="Événement ou fin de bannière"')}${field('Date','agendaDate','','date')}<label class="hsr-field">Type<select data-hsr-agenda="kind">${options(['Événement','Bannière','Mémoire du Chaos','Fiction pure','Ombre apocalyptique','Mise à jour','Autre'].map(x=>({_id:x,_name:x})),'Événement')}</select></label><button class="button-primary" data-hsr-action="add-agenda">Ajouter</button></div><div class="hsr-agenda-list">${data.agenda.map((row,i)=>`<article><time>${esc(row.date)}</time><span><b>${esc(row.title)}</b><small>${esc(row.kind)}</small></span><button data-hsr-delete-agenda="${i}">×</button></article>`).join('')||'<p class="hsr-note">Ton agenda Star Rail est vide. Les rappels restent sur cet appareil.</p>'}</div>`,'⌖')}`}
function renderLore(chars){return `<section class="hsr-workspace-hero lore"><div><span>ARCHIVES · PENACONY À L’UNIVERS</span><h2>Explore le casting Star Rail</h2><p>Fiches et kits détaillés sont accessibles dans la bibliothèque. Cette page sert de raccourci pour parcourir les personnages et garder le lore dans son univers.</p></div></section><div class="hsr-lore-grid">${chars.map(char=>`<button data-hsr-open-character="${esc(char._id)}">${icon(char)}<span><b>${esc(char._name)}</b><small>${esc(char.pathText||char.path||'Voie inconnue')} · ${esc(char.elementText||char.element||'Élément')}</small></span><i>Ouvrir la fiche ↗</i></button>`).join('')}</div>`}
function dayKey(date=new Date()){const shifted=new Date(date);shifted.setHours(shifted.getHours()-4);return shifted.toISOString().slice(0,10)}
function dashboardWeekKey(date=new Date()){const shifted=new Date(date.getTime()-4*3600000);shifted.setHours(0,0,0,0);shifted.setDate(shifted.getDate()-(shifted.getDay()+6)%7);return shifted.toLocaleDateString('sv-SE')}
function ensureCurrencyWeek(war){const now=new Date(),[hour,minute]=String(war.serverReset||'04:00').split(':').map(Number),reset=new Date(now);reset.setHours(Number.isFinite(hour)?hour:4,Number.isFinite(minute)?minute:0,0,0);const day=(now.getDay()+6)%7;reset.setDate(now.getDate()-day);if(now<reset)reset.setDate(reset.getDate()-7);const key=reset.toISOString().slice(0,10);if(war.weekKey!==key){war.weekKey=key;war.weeklyPoints=0;war.weekRuns=0;war.firstStandard=false;war.firstOverclock=false;}return {key,next:new Date(reset.getTime()+7*86400000)}}
function renderHsrDashboard(data,chars,teams){const daily=data.dashboardDaily||{date:'',done:[]},today=dayKey(),done=daily.date===today?daily.done||[]:[],weekly=data.dashboardWeekly||defaults().dashboardWeekly,currentWeek=dashboardWeekKey();if(weekly.week!==currentWeek){weekly.week=currentWeek;weekly.done=[]}if(!Array.isArray(weekly.done))weekly.done=[];if(!Array.isArray(weekly.tasks))weekly.tasks=defaults().dashboardWeekly.tasks;data.dashboardWeekly=weekly;const weeklyDone=new Set(weekly.done),war=data.currencyWar,week=ensureCurrencyWeek(war);let wallet={};try{wallet=JSON.parse(localStorage.getItem("astralis:resources:hsr")||"{}")}catch{}const jade=Number(wallet.jade??data.warp?.jade)||0,passes=Number(wallet.pass??data.warp?.passes)||0,special=Number(wallet.special??data.warp?.special)||0;const shortcuts=[['hsr-builds','Builds & reliques','Six pièces, cônes et variantes','◈'],['hsr-lab','Laboratoire de combat','Actions, rotations et dégâts','⚔'],['hsr-calc','Calc Sheets','Comparer équipes et cycles','▤'],['hsr-farm','Plan de farm','Traces, ascension et matériaux','⌂'],['hsr-endgame','Endgame','MoC · Fiction pure · Ombre','✦'],['hsr-wishes','Warp & objectifs','Jades, passes, pity et garanties','✧'],['hsr-events','Agenda Star Rail','Événements et échéances locales','⌖'],['hsr-lore','Archives','Personnages et voies','⌘']];return `<main class="hsr-command" data-hsr-hub data-hsr-section="hsr-dashboard"><header class="hsr-command-hero"><div><span class="hsr-command-kicker"><img src="/assets/ui/game-starrail.png" alt="" width="22" height="22"> HONKAI: STAR RAIL · POSTE DE COMMANDEMENT</span><h1>À bord de l’Astral Express.</h1><p>Ta progression, ton équipe et les prochains objectifs de l’univers, réunis dans un espace conçu pour Star Rail.</p><div class="hsr-command-actions"><button data-nav="hsr-currency-wars" class="hsr-primary-action">⟡ Reprendre Currency Wars</button><button data-nav="hsr-builds">Ouvrir mes builds ↗</button><button data-nav="characters">Parcourir le roster ↗</button></div></div><div class="hsr-express-emblem" aria-hidden="true"><span>✦</span><i></i><b>ASTRAL<br>EXPRESS</b></div><div class="hsr-command-stars" aria-hidden="true"></div></header><section class="hsr-resource-strip"><article><img src="/assets/ui/currency-starrail-jade.png" alt=""><span><small>JADES STELLAIRES</small><b>${jade.toLocaleString('fr-FR')}</b></span><button data-nav="hsr-wishes">＋</button></article><article><img src="/assets/ui/currency-starrail-special-pass.png" alt=""><span><small>PASS SPÉCIAL</small><b>${special}</b></span><button data-nav="hsr-wishes">＋</button></article><article><img src="/assets/ui/currency-starrail-pass.png" alt=""><span><small>PASS STAR RAIL</small><b>${passes}</b></span><button data-nav="hsr-wishes">＋</button></article><article class="hsr-warp-summary"><span><small>SAUTS DISPONIBLES</small><b>${special+passes+Math.floor(jade/160)}</b></span><button data-nav="hsr-wishes">Voir mon objectif ↗</button></article></section><div class="hsr-command-grid"><section class="hsr-command-panel hsr-daily-panel"><header><div><small>ROUTINE QUOTIDIENNE</small><h2>Avant de quitter le train</h2></div><span>${done.length}/5</span></header><div class="hsr-checklist">${[['training','Entraînement quotidien','Terminer les 500 points d’entraînement'],['assignments','Expéditions','Récupérer les personnages envoyés'],['power','Énergie','Dépenser ou planifier la puissance'],['war','Currency Wars','Vérifier les points hebdomadaires'],['endgame','Défis périodiques','Actualiser les équipes et résultats']].map(([id,label,hint])=>`<label class="hsr-daily-item ${done.includes(id)?'is-done':''}"><input type="checkbox" data-hsr-daily="${id}" ${done.includes(id)?'checked':''}><span class="hsr-daily-check">${done.includes(id)?'✓':'·'}</span><span><b>${label}</b><small>${hint}</small></span><i>›</i></label>`).join('')}</div><p class="hsr-command-footnote">Ta checklist se renouvelle automatiquement chaque jour à 04:00, heure locale. La réinitialisation serveur peut varier selon la région.</p></section><section class="hsr-command-panel hsr-weekly-panel"><header><div><small>ROUTE HEBDOMADAIRE · RESET LUNDI 04:00</small><h2>Cette semaine dans l’Express</h2></div><span>${weeklyDone.size}/${weekly.tasks.length}</span></header><div class="hsr-weekly-meter" role="progressbar" aria-label="Progression hebdomadaire" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${weekly.tasks.length?Math.round(weeklyDone.size/weekly.tasks.length*100):0}"><i style="width:${weekly.tasks.length?Math.round(weeklyDone.size/weekly.tasks.length*100):0}%"></i></div><div class="hsr-weekly-list">${weekly.tasks.map(task=>`<div class="hsr-weekly-row ${weeklyDone.has(task.id)?'is-done':''}"><label><input type="checkbox" data-hsr-weekly="${esc(task.id)}" ${weeklyDone.has(task.id)?'checked':''}><span><b>${esc(task.label)}</b><small>${esc(task.hint||'Objectif Star Rail')}</small></span></label><button type="button" data-hsr-weekly-remove="${esc(task.id)}" aria-label="Retirer ${esc(task.label)}">×</button></div>`).join('')||'<p class="hsr-command-footnote">Ajoute un objectif pour cette semaine.</p>'}</div><form class="hsr-weekly-add" data-hsr-weekly-add><input name="label" maxlength="64" required placeholder="Nouvel objectif hebdomadaire" aria-label="Nouvel objectif hebdomadaire"><input name="hint" maxlength="100" placeholder="Détail (facultatif)" aria-label="Détail de l’objectif"><button type="submit">＋ Ajouter</button></form><p class="hsr-command-footnote">Tes objectifs sont stockés sur cet appareil et se renouvellent au reset hebdomadaire.</p></section><section class="hsr-command-panel hsr-war-widget"><header><div><small>MODE PERMANENT · SAISON EN COURS</small><h2>Currency Wars</h2></div><span class="hsr-live-pip">SUIVI LOCAL</span></header><p>${esc(war.season||'Voyage Into the Canvas')} · ${war.employees.length}/10 employés · ${war.bonds.length} bonds suivis</p><div class="hsr-war-score"><div><small>POINTS HEBDOMADAIRES</small><b>${Number(war.weeklyPoints)||0}</b></div><div><small>ASCENSION</small><b>${Number(war.ascensionPoints)||0}</b></div></div><div class="hsr-war-progress"><span style="width:${Math.min(100,(Number(war.weeklyPoints)||0)/1000*100)}%"></span></div><small class="hsr-reset-note">Prochain repère hebdomadaire : lundi 04:00 · ${Math.max(0,Math.ceil((week.next-Date.now())/3600000))} h</small><button class="hsr-inline-link" data-nav="hsr-currency-wars">Ouvrir le centre de saison ↗</button></section><section class="hsr-command-panel hsr-team-widget"><header><div><small>ESCouADE ENREGISTRÉE</small><h2>Tes équipes</h2></div><button data-nav="teams">Gérer ↗</button></header>${teams.slice(0,2).map((team,index)=>`<article class="hsr-team-row"><span class="hsr-team-index">0${index+1}</span><div><b>${esc(team.name||'Escouade sans nom')}</b><small>${(team.members||[]).map(member=>esc(chars.find(char=>String(char._id)===String(member.character??member.characterId))?._name||'Emplacement libre')).join(' · ')||'4 emplacements à composer'}</small></div><i>›</i></article>`).join('')||`<div class="hsr-team-empty"><span>✧</span><b>Ton escouade prend forme ici</b><p>Crée une équipe Star Rail, puis reviens pour ses raccourcis et sa composition.</p><button data-nav="teams">Créer une équipe ↗</button></div>`}</section><section class="hsr-command-panel hsr-roster-widget"><header><div><small>PERSONNAGES RÉFÉRENCÉS</small><h2>Le roster à portée</h2></div><button data-nav="characters">Tout voir · ${chars.length} ↗</button></header><div class="hsr-roster-row">${chars.filter(char=>!char.preRelease).slice(0,12).map(char=>`<button data-detail="${esc(char._id)}" data-item-category="character" title="${esc(char._name)}">${icon(char)}</button>`).join('')}</div><p>Ouvre une fiche ou choisis tes prochains builds, sans quitter le tableau de bord.</p></section></div><section class="hsr-command-shortcuts"><header><div><small>ATELIER DE L’EXPRESS</small><h2>Tout Star Rail, en un saut</h2></div></header><div>${shortcuts.map(([route,title,description,mark])=>`<button data-nav="${route}"><i>${mark}</i><span><b>${title}</b><small>${description}</small></span><em>↗</em></button>`).join('')}</div></section></main>`}
function renderCurrencyWars(data,chars){const w=data.currencyWar,week=ensureCurrencyWeek(w),employeeSet=new Set(w.employees||[]),bonds=(w.bonds||[]),roster=(w.employees||[]).map((id,index)=>{const char=chars.find(item=>String(item._id)===String(id));return `<article class="hsr-war-employee">${icon(char)}<span><b>${esc(char?._name||'Employé inconnu')}</b><small>Emplacement ${String(index+1).padStart(2,'0')} · ${esc(char?.pathText||char?.path||'Voie à vérifier')}</small></span><button data-hsr-remove-employee="${esc(id)}" aria-label="Retirer">×</button></article>`}).join('');const runs=w.runs||[];return `<section class="hsr-war-hero"><div><span>MODE PERMANENT · SAISON 4.7</span><h2>Currency Wars : Voyage Into the Canvas</h2><p>Ton centre de préparation et d’historique pour le mode roguelike. Roster, bonds, score hebdomadaire, ascension et récompenses restent modifiables et stockés sur cet appareil.</p><div class="hsr-war-tags"><b>Escapade · compagnon de voyage</b><b>Plot Armor · choix avant les boss des plans 1 et 2</b></div></div><div class="hsr-war-season-mark"><span>✧</span><small>INTERASTRAL<br>PEACE GUIDE</small></div></section><div class="hsr-war-kpis"><article><small>POINTS CETTE SEMAINE</small><b>${Number(w.weeklyPoints)||0}</b><span>réinitialisation calculée lundi à 04:00</span></article><article><small>POINTS D’ASCENSION</small><b>${Number(w.ascensionPoints)||0}</b><span>progression de saison, saisie ou tenue à jour après chaque run</span></article><article><small>EMPLOYÉS PRÉPARÉS</small><b>${w.employees.length}<i>/10</i></b><span>composition personnelle du roster</span></article><article><small>BONDS SUIVIS</small><b>${bonds.length}</b><span>combinaisons à surveiller pendant les runs</span></article></div><div class="hsr-war-layout"><div class="hsr-war-main">${card('Journaliser une partie','RUN · POINTS · RÉCOMPENSES',`<div class="hsr-form-grid"><label class="hsr-field">Difficulté<select data-hsr-war="difficulty">${options(['Standard Gambit','Overclock Gambit'].map(x=>({_id:x,_name:x})), 'Standard Gambit')}</select></label><label class="hsr-field">Résultat<select data-hsr-war="result">${options(['Victoire','Défaite','Abandonnée'].map(x=>({_id:x,_name:x})), 'Victoire')}</select></label>${field('Points hebdomadaires gagnés','points','','number','min="0" step="1"')}${field('Points d’ascension gagnés','ascension','','number','min="0" step="1"')}${field('Plan atteint','plane','','number','min="0" max="6"')}${field('Boss / note de run','boss','','text','placeholder="Employé choisi · boss · détail utile"')}<label class="hsr-check"><input type="checkbox" data-hsr-war="firstClear"> Première victoire standard</label><label class="hsr-check"><input type="checkbox" data-hsr-war="firstOverclock"> Première victoire Overclock</label><label class="hsr-check full"><input type="checkbox" data-hsr-war="claimed"> Récompenses de palier récupérées en jeu</label></div><button class="button-primary" data-hsr-action="log-war-run">Enregistrer cette partie</button><p class="hsr-note">Les points saisis sont additionnés au total de la semaine; une défaite ou partie abandonnée n’ajoute rien. Le statut « récompenses récupérées » est une confirmation personnelle et ne réclame rien en jeu.</p>`,'↗')}${card('Composition de dix employés','PRÉPARATION DE ROSTER',`<p>Ajoute les personnages que tu veux préparer. Cette liste est ton aide-mémoire; elle ne suppose pas qu’un personnage soit disponible ou fort dans chaque environnement de saison.</p><label class="hsr-field">Ajouter un personnage<select data-hsr-war-add><option value="">Choisir dans le roster…</option>${chars.filter(char=>!employeeSet.has(String(char._id))).map(char=>`<option value="${esc(char._id)}">${esc(char._name)} · ${esc(char.pathText||char.path||'Voie inconnue')}</option>`).join('')}</select></label><div class="hsr-war-roster">${roster||'<p class="hsr-note">Les dix emplacements sont à construire selon tes personnages et tes plans.</p>'}</div>`,'♙')}${card('Suivre les bonds','SYNERGIES & INDEX',`<div class="hsr-war-bond-add"><input data-hsr-war-bond placeholder="Nom du bond ou de la combinaison"><button data-hsr-action="add-war-bond">＋ Ajouter</button></div><div class="hsr-war-bonds">${bonds.map((bond,index)=>`<label><input type="checkbox" data-hsr-war-bond-done="${index}" ${bond.done?'checked':''}><span><b>${esc(bond.name)}</b><small>${esc(bond.note||'Combinaison à vérifier dans l’index du jeu')}</small></span><button data-hsr-remove-bond="${index}" aria-label="Supprimer">×</button></label>`).join('')||'<p class="hsr-note">Ajoute ici les bonds que tu veux expérimenter. La liste est personnelle afin de ne pas inventer un index complet des effets.</p>'}</div><div class="hsr-official-bonds"><small>NOUVEAUX EXEMPLES PRÉSENTÉS POUR LA SAISON</small><span>Astropolis Merchant Guild</span><span>Phantasmoon Games</span><span>Trailblaze Silver Rail</span><span>The Grand Restaurant</span><span>Intertwined Dreamscapes</span><span>High-Cloud Quintet</span></div>`,'◇')}</div><aside class="hsr-war-side">${card('État de la saison','AUTOMATISATION LOCALE',`<div class="hsr-war-reset"><span>PROCHAIN RESET HEBDOMADAIRE</span><b>Lundi · 04:00</b><small>Fuseau de l’appareil : ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone||'heure locale')}</small></div><label class="hsr-check"><input type="checkbox" data-hsr-war="reminder" ${w.reminder===false?'':'checked'}> Afficher le rappel dans le tableau de bord</label><label class="hsr-field">Heure serveur indicative<input type="time" data-hsr-war="serverReset" value="${esc(w.serverReset||'04:00')}"></label><div class="hsr-war-milestones"><h4>Suivi des premières victoires</h4><label><input type="checkbox" data-hsr-war="firstStandard" ${w.firstStandard?'checked':''}> Gambit standard terminé</label><label><input type="checkbox" data-hsr-war="firstOverclock" ${w.firstOverclock?'checked':''}> Gambit Overclock terminé</label></div><p class="hsr-note">Le jeu ne fournit pas de synchronisation de compte à Astralis : les runs, points et récompenses sont notés manuellement. Le compteur hebdomadaire se remet à zéro localement selon le lundi 04:00 choisi.</p>`,'⌁')}${card('Historique des runs','TES DERNIÈRES PARTIES',`<div class="hsr-war-runs">${runs.slice(0,12).map(run=>`<article><span class="hsr-run-mark ${run.result==='Victoire'?'won':''}">${run.result==='Victoire'?'✓':'·'}</span><div><b>${esc(run.difficulty)} · ${esc(run.result)}</b><small>${new Date(run.date).toLocaleString('fr-FR')} · Plan ${esc(run.plane||'—')} · ${esc(run.boss||'')}</small></div><strong>+${Number(run.points)||0}<small> pts</small></strong></article>`).join('')||'<p class="hsr-note">Tes runs apparaîtront ici et seront ajoutés au score hebdomadaire.</p>'}</div>`,'⌖')}</aside></div><footer class="hsr-war-source">Données de saison d’après <a href="https://www.hoyolab.com/article/47271769?reply=1" target="_blank" rel="noopener noreferrer">l’annonce officielle HoYoLAB</a>. Récompenses réclamées, inventaire et résultats restent à confirmer dans le jeu.</footer>`}
export function renderHsrWorkspace(section,catalogs,teams=[]){fieldMode=section==='hsr-lab'?'lab':section==='hsr-wishes'?'warp':section==='hsr-currency-wars'?'war':'field';const data={...defaults(),...read()};data.warp={...defaults().warp,...data.warp};data.currencyWar={...defaults().currencyWar,...data.currencyWar};data.farm||={};data.calc||=[];data.builds||=[];data.endgame||=[];data.agenda||=[];const chars=catalogs['hsr:character']||[],cones=catalogs['hsr:weapon']||[],relics=catalogs['hsr:artifact']||[],materials=catalogs['hsr:material']||[],page=routes[section];if(!page)return '';if((section==='hsr-builds'||section==='hsr-lab'||section==='hsr-currency-wars')&&!chars.length)return `<div class="loading-panel">Chargement du roster Star Rail…</div>`;if(section==='hsr-dashboard')return renderHsrDashboard(data,chars,teams);return `<main class="hsr-hub" data-hsr-hub data-hsr-section="${section}"><div class="hsr-subnav">${Object.entries(routes).map(([key,[label]])=>`<button class="${section===key?'active':''}" data-nav="${key}">${esc(label)}</button>`).join('')}</div><header class="hsr-page-heading"><span>✦ ${esc(page[0].toUpperCase())}</span><h1>${esc(page[1])}</h1></header>${section==='hsr-builds'?renderBuilds(data,chars,cones,relics):section==='hsr-lab'?renderLab(data,chars):section==='hsr-calc'?renderCalc(data,teams):section==='hsr-farm'?renderFarm(data,chars,materials):section==='hsr-endgame'?renderEndgame(data,teams):section==='hsr-currency-wars'?renderCurrencyWars(data,chars):section==='hsr-wishes'?renderWarp(data):section==='hsr-events'?renderAgenda(data):renderLore(chars)}</main>`}
function collectFields(root,selector){const out={};root.querySelectorAll(selector).forEach(el=>{const value=el.type==='checkbox'?el.checked:el.value;out[el.dataset.hsrField||el.dataset.hsrLab||el.dataset.hsrWarp||el.dataset.hsrFarm||el.dataset.hsrEndgame||el.dataset.hsrAgenda]=value});return out}
function currentDraft(){const d=read();return {...defaults(),...d,warp:{...defaults().warp,...d.warp},currencyWar:{...defaults().currencyWar,...d.currencyWar}}}
function persistDraft(root){const data=currentDraft(),section=root.dataset.hsrSection,fields=collectFields(root,'[data-hsr-field]');if(section==='hsr-lab'){data.lab={...(data.lab||{}),...fields,...collectFields(root,'[data-hsr-lab]')};}else if(section==='hsr-wishes'){for(const [key,value] of Object.entries(fields))data.warp[key]=/Guarantee/.test(key)?value:Number(value)||0;}else if(section==='hsr-currency-wars'){const war=data.currencyWar;root.querySelectorAll('[data-hsr-war]').forEach(el=>war[el.dataset.hsrWar]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value)||0:el.value); }else if(section==='hsr-dashboard'){/* Le tableau de bord ne modifie que sa checklist dédiée. */}else{data.buildDraft={...(data.buildDraft||{}),...fields};data.buildDraft.stats={...(data.buildDraft.stats||{}),...Object.fromEntries([...root.querySelectorAll('[data-hsr-field]')].filter(el=>statFields.some(([key])=>key===el.dataset.hsrField)).map(el=>[el.dataset.hsrField,el.value]))};data.buildDraft.relics=slots.map((_,i)=>{const previous=data.buildDraft.relics?.[i]||{};const next={...previous};root.querySelectorAll(`[data-hsr-relic="${i}"]`).forEach(el=>next[el.dataset.relicField]=el.value);return next});}root.querySelectorAll('[data-hsr-warp]').forEach(el=>data.warp[el.dataset.hsrWarp]=el.type==='checkbox'?el.checked:Number(el.value)||0);if(data.builds.find(row=>row.id===data.activeBuild)&&section==='hsr-builds')data.builds=data.builds.map(row=>row.id===data.activeBuild?{...row,...data.buildDraft}:row);write(data);return data}
function rerender(){document.dispatchEvent(new CustomEvent('astralis:hsr-workspace-changed'))}
function rerenderKeepingFocus(element){const key=element.dataset.hsrLab?['data-hsr-lab',element.dataset.hsrLab]:element.dataset.hsrWarp?['data-hsr-warp',element.dataset.hsrWarp]:null,selection=typeof element.selectionStart==='number'?element.selectionStart:null;if(!key){rerender();return}rerender();requestAnimationFrame(()=>{const next=document.querySelector(`[${key[0]}="${CSS.escape(key[1])}"]`);if(!next)return;next.focus({preventScroll:true});if(selection!==null&&next.setSelectionRange)next.setSelectionRange(selection,selection)})}
let wired=false;
export function initHsrWorkspace(){if(wired)return;wired=true;document.addEventListener('input',event=>{const root=event.target.closest('[data-hsr-hub]');if(!root)return;const data=persistDraft(root);if(event.target.dataset.hsrLab||event.target.dataset.hsrWarp||['hsr-lab','hsr-wishes'].includes(root.dataset.hsrSection)){write(data);rerenderKeepingFocus(event.target)}});document.addEventListener('submit',event=>{const form=event.target.closest('[data-hsr-weekly-add]');if(!form)return;event.preventDefault();const d=currentDraft(),weekly=d.dashboardWeekly||defaults().dashboardWeekly,label=String(new FormData(form).get('label')||'').trim(),hint=String(new FormData(form).get('hint')||'').trim();if(!label)return;if(weekly.tasks.length>=20)return;weekly.tasks.push({id:id(),label:label.slice(0,64),hint:hint.slice(0,100)});d.dashboardWeekly=weekly;write(d);rerender()});document.addEventListener('change',event=>{const root=event.target.closest('[data-hsr-hub]');if(!root)return;const data=persistDraft(root);if(root.dataset.hsrSection==='hsr-dashboard'&&event.target.matches('[data-hsr-weekly]')){const weekly=data.dashboardWeekly||defaults().dashboardWeekly;if(weekly.week!==dashboardWeekKey()){weekly.week=dashboardWeekKey();weekly.done=[]}const task=event.target.dataset.hsrWeekly;weekly.done=event.target.checked?[...new Set([...weekly.done,task])]:weekly.done.filter(item=>item!==task);data.dashboardWeekly=weekly;write(data);rerender();return}if(root.dataset.hsrSection==='hsr-dashboard'&&event.target.matches('[data-hsr-daily]')){const today=dayKey(),daily=data.dashboardDaily;if(daily.date!==today){daily.date=today;daily.done=[]}const task=event.target.dataset.hsrDaily;daily.done=event.target.checked?[...new Set([...daily.done,task])]:daily.done.filter(item=>item!==task);write(data);rerender();return}if(event.target.matches('[data-hsr-war-add]')){const value=event.target.value;if(value&&!data.currencyWar.employees.some(item=>String(item)===String(value))&&data.currencyWar.employees.length<10)data.currencyWar.employees.push(value);write(data);rerender();return}if(event.target.matches('[data-hsr-war-bond-done]')){data.currencyWar.bonds[Number(event.target.dataset.hsrWarBondDone)].done=event.target.checked;write(data);rerender();}});document.addEventListener('click',event=>{const root=event.target.closest('[data-hsr-hub]');if(!root)return;const button=event.target.closest('button');if(!button)return;let d=currentDraft();if(button.dataset.hsrWeeklyRemove){d.dashboardWeekly||=defaults().dashboardWeekly;d.dashboardWeekly.tasks=d.dashboardWeekly.tasks.filter(task=>task.id!==button.dataset.hsrWeeklyRemove);d.dashboardWeekly.done=d.dashboardWeekly.done.filter(task=>task!==button.dataset.hsrWeeklyRemove);write(d);rerender();return}if(button.dataset.hsrLoadBuild){d.activeBuild=button.dataset.hsrLoadBuild;const build=d.builds.find(row=>row.id===d.activeBuild);d.buildDraft=build?structuredClone(build):{};write(d);rerender();return}if(button.dataset.hsrOpenCharacter){document.dispatchEvent(new CustomEvent('astralis:hsr-open-character',{detail:{id:button.dataset.hsrOpenCharacter}}));return}if(button.dataset.hsrDeleteCalc!=null){d.calc.splice(Number(button.dataset.hsrDeleteCalc),1);write(d);rerender();return}if(button.dataset.hsrDeleteFarm){delete d.farm[button.dataset.hsrDeleteFarm];write(d);rerender();return}if(button.dataset.hsrDeleteEndgame!=null){d.endgame.splice(Number(button.dataset.hsrDeleteEndgame),1);write(d);rerender();return}if(button.dataset.hsrDeleteAgenda!=null){d.agenda.splice(Number(button.dataset.hsrDeleteAgenda),1);write(d);rerender();return}if(button.dataset.hsrRemoveHit!=null){d.lab||={};d.lab.sequence||=[];d.lab.sequence.splice(Number(button.dataset.hsrRemoveHit),1);write(d);rerender();return}if(button.dataset.hsrRemoveEmployee){d.currencyWar.employees=d.currencyWar.employees.filter(item=>String(item)!==String(button.dataset.hsrRemoveEmployee));write(d);rerender();return}if(button.dataset.hsrRemoveBond!=null){d.currencyWar.bonds.splice(Number(button.dataset.hsrRemoveBond),1);write(d);rerender();return}
 if(button.dataset.hsrAction==='new-build'){d.activeBuild='';d.buildDraft={name:`Build ${d.builds.length+1}`,level:80,eidolon:0,coneLevel:80,relics:slots.map(([key,label,main])=>({slot:key,label,main,level:15,subs:''})),stats:{}};write(d);rerender()}
 if(button.dataset.hsrAction==='save-build'){const draft=persistDraft(root).buildDraft||{};const saved={...draft,id:d.activeBuild||draft.id||id(),name:draft.name||`Build ${d.builds.length+1}`};const at=d.builds.findIndex(row=>row.id===saved.id);if(at<0)d.builds.push(saved);else d.builds[at]=saved;d.activeBuild=saved.id;d.buildDraft=saved;write(d);rerender()}
 if(button.dataset.hsrAction==='delete-build'){d.builds=d.builds.filter(x=>x.id!==d.activeBuild);d.activeBuild='';d.buildDraft={};write(d);rerender()}
 if(button.dataset.hsrAction==='new-calc'){d.calc.push({id:id(),name:`Escouade ${d.calc.length+1}`,dpr:'',dps:'',cycle:'',rotation:''});write(d);rerender()}
 if(button.dataset.hsrAction==='add-farm'){const vals=collectFields(root,'[data-hsr-farm]'),char=root.querySelector('[data-hsr-farm="character"]')?.selectedOptions?.[0],material=root.querySelector('[data-hsr-farm="material"]')?.selectedOptions?.[0];if(!vals.character||!vals.material)return;const key=id();d.farm[key]={...vals,id:key,characterName:char?.textContent||'',materialName:material?.textContent||'',needed:Number(root.querySelector('[data-hsr-field="needed"]')?.value)||0,owned:Number(root.querySelector('[data-hsr-field="owned"]')?.value)||0};write(d);rerender()}
 if(button.dataset.hsrAction==='save-endgame'){const vals=collectFields(root,'[data-hsr-endgame]'),team=root.querySelector('[data-hsr-endgame="team"]')?.selectedOptions?.[0];d.endgame.unshift({name:root.querySelector('[data-hsr-field="endgameName"]')?.value||'Session Star Rail',date:root.querySelector('[data-hsr-field="date"]')?.value||new Date().toISOString().slice(0,10),side1:root.querySelector('[data-hsr-field="side1"]')?.value||'',side2:root.querySelector('[data-hsr-field="side2"]')?.value||'',...vals,teamName:team?.textContent||'',notes:root.querySelector('[data-hsr-endgame="notes"]')?.value||''});write(d);rerender()}
 if(button.dataset.hsrAction==='save-warp'){d=persistDraft(root);localStorage.setItem('astralis:resources:hsr',JSON.stringify({jade:Number(d.warp.jade)||0,pass:Number(d.warp.passes)||0,special:Number(d.warp.special)||0}));write(d);rerender()}
 if(button.dataset.hsrAction==='add-war-bond'){const input=root.querySelector('[data-hsr-war-bond]'),name=input?.value?.trim();if(name&&!d.currencyWar.bonds.some(bond=>bond.name.toLowerCase()===name.toLowerCase()))d.currencyWar.bonds.push({name,done:false,note:'À vérifier dans l’index de la saison'});write(d);rerender()}
 if(button.dataset.hsrAction==='log-war-run'){ensureCurrencyWeek(d.currencyWar);const values={};root.querySelectorAll('[data-hsr-war]').forEach(el=>values[el.dataset.hsrWar]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value)||0:el.value);const run={...values,date:new Date().toISOString(),result:values.result||'Victoire',difficulty:values.difficulty||'Standard Gambit'};d.currencyWar.runs.unshift(run);if(run.result==='Victoire'){d.currencyWar.weeklyPoints+=Number(run.points)||0;d.currencyWar.ascensionPoints+=Number(run.ascension)||0;d.currencyWar.weekRuns=(Number(d.currencyWar.weekRuns)||0)+1}if(run.firstClear)d.currencyWar.firstStandard=true;if(run.firstOverclock)d.currencyWar.firstOverclock=true;write(d);rerender()}
 if(button.dataset.hsrAction==='add-agenda'){const kind=root.querySelector('[data-hsr-agenda="kind"]')?.value||'Événement';d.agenda.unshift({title:root.querySelector('[data-hsr-field="agendaTitle"]')?.value||'Repère Star Rail',date:root.querySelector('[data-hsr-field="agendaDate"]')?.value||'',kind});write(d);rerender()}
 if(button.dataset.hsrAction==='add-hit'){d=persistDraft(root);d.lab||={};d.lab.sequence||=[];d.lab.sequence.push({name:root.querySelector('[data-hsr-lab="sequenceName"]')?.value||'Action',damage:Number(root.querySelector('[data-hsr-lab="sequenceDamage"]')?.value)||0,hits:Number(root.querySelector('[data-hsr-lab="sequenceHits"]')?.value)||1});write(d);rerender()}
 });document.addEventListener('input',event=>{const el=event.target;if(!el.matches('[data-hsr-calc]'))return;const d=currentDraft(),row=d.calc[Number(el.dataset.hsrCalc)];if(!row)return;row[el.dataset.calcField]=el.value;if(row.dpr&&Number(row.cycle)>0){row.dps=(Number(row.dpr)/Number(row.cycle)).toFixed(2);const output=document.querySelector(`[data-hsr-calc="${el.dataset.hsrCalc}"][data-calc-field="dps"]`);if(output)output.value=row.dps}write(d)});
}
export const hsrWorkspaceRoutes=routes;
